@sig trait ActionArbitration_Api {
  def id: Art.BridgeId
  def emergency_state_Id : Art.PortId
  def quotation_proposal_Id : Art.PortId
  def procurement_proposal_Id : Art.PortId
  def production_proposal_Id : Art.PortId
  def dispatch_proposal_Id : Art.PortId
  def selected_action_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var selected_action: Factory_Dispatch_Coordinator.DispatchAction.Type = $

  def put_selected_action(value : Factory_Dispatch_Coordinator.DispatchAction.Type) : Unit = {
    Contract(
      Modifies(selected_action),
      Ensures(
        selected_action == value
      )
    )
    Spec {
      selected_action = value
    }

    Art.putValue(selected_action_Id, Factory_Dispatch_Coordinator.DispatchAction_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

